mapper.select:
select co.id, p.id as productId, p.title, co.order_no, co.purpose, co.style, co.status, co.material, co.min_budget, co.max_budget, co.size, co.remark, co.colors as colorOptions, co.patterns as patternOptions, co.images, co.created_at, co.is_confirmed, co.quote, co.proposal_image, co.worker_id, u.nick_name as workerName, co.quote_time, co.proposal_time from custom_orders as co left join products as p on co.product_id = p.id left join users as u on co.worker_id=u.id where co.user_id=#{currentUserId}
and co.status=#{status}
and (co.purpose ilike concat('%',#{key},'%') or co.style ilike concat('%',#{key},'%') or co.material ilike concat('%',#{key},'%') or co.order_no ilike concat('%',#{key},'%') or p.title ilike concat('%',#{key},'%') or co.remark ilike concat('%',#{key},'%') )
order by co.created_at Desc
